                migrate(c);
                return;
            } catch (SQLException e) {
                last = e;
                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); break; }
            }
        }
        throw new IllegalStateException("Banco de dados indisponível", last);
